function getRandomDevice() {
  const item = ALL_DEVICES[Math.floor(Math.random() * ALL_DEVICES.length)];
  const parts = item.split(" - ");
  return {
    fullName: item,
    model: parts[0] || item,
    os: parts[1] || "Android 14"
  };
}
