const DB_NAME = "zeio_theme_storage";
const DB_VERSION = 1;
const STORE_NAME = "custom_videos";
const META_KEY = "zeio_custom_themes_meta";
function getCustomThemesMeta() {
  try {
    const raw = localStorage.getItem(META_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}
function saveCustomThemesMeta(list) {
  try {
    localStorage.setItem(META_KEY, JSON.stringify(list));
  } catch (e) {
    console.warn("Failed to save custom themes meta:", e);
  }
}
function openDB() {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === "undefined") {
      return reject(new Error("IndexedDB not supported"));
    }
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db2 = request.result;
      if (!db2.objectStoreNames.contains(STORE_NAME)) {
        db2.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}
async function saveVideoBlob(id, blob) {
  try {
    const db2 = await openDB();
    return new Promise((resolve, reject) => {
      const tx = db2.transaction(STORE_NAME, "readwrite");
      const store = tx.objectStore(STORE_NAME);
      const req = store.put({ id, blob });
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  } catch (e) {
    console.error("Error saving video blob to IndexedDB:", e);
    throw e;
  }
}
async function getVideoBlob(id) {
  try {
    const db2 = await openDB();
    return new Promise((resolve, reject) => {
      const tx = db2.transaction(STORE_NAME, "readonly");
      const store = tx.objectStore(STORE_NAME);
      const req = store.get(id);
      req.onsuccess = () => resolve(req.result ? req.result.blob : null);
      req.onerror = () => reject(req.error);
    });
  } catch (e) {
    console.warn("Error fetching video blob:", e);
    return null;
  }
}
async function deleteVideoBlob(id) {
  try {
    const db2 = await openDB();
    return new Promise((resolve, reject) => {
      const tx = db2.transaction(STORE_NAME, "readwrite");
      const store = tx.objectStore(STORE_NAME);
      const req = store.delete(id);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  } catch {
  }
}
